'use strict';

// MODULES //

var resolve = require( 'path' ).resolve;
var tape = require( 'tape' );
var remark = require( 'remark' );
var readFileSync = require( '@stdlib/fs/read-file' ).sync;
var string2buffer = require( '@stdlib/buffer/from-string' );
var array2buffer = require( '@stdlib/buffer/from-array' );
var keys = require( '@stdlib/utils/keys' );
var convert = require( './../lib' );


// FIXTURES //

var opts = {
	'encoding': 'utf8'
};
var FIXTURES_DIR = resolve( __dirname, 'fixtures' );
var FIXTURE = readFileSync( resolve( FIXTURES_DIR, 'readme', 'file.md.txt' ), opts ); // eslint-disable-line n/no-sync
var TUTORIAL_FIXTURE = readFileSync( resolve( FIXTURES_DIR, 'tutorial', 'file.md.txt' ), opts ); // eslint-disable-line n/no-sync


// FUNCTIONS //

/**
* Returns the first semantic node matching a type and optional role.
*
* @private
* @param {Array} children - semantic nodes
* @param {string} type - node type
* @param {string} [role] - semantic role
* @returns {(Object|null)} semantic node or null
*/
function findNode( children, type, role ) {
	var out;
	var i;

	for ( i = 0; i < children.length; i++ ) {
		if (
			children[ i ].type === type &&
			( !role || children[ i ].role === role )
		) {
			return children[ i ];
		}
		if ( children[ i ].children ) {
			out = findNode( children[ i ].children, type, role );
			if ( out ) {
				return out;
			}
		}
	}
	return null;
}

/**
* Returns all semantic nodes matching a type.
*
* @private
* @param {Array} children - semantic nodes
* @param {string} type - node type
* @returns {Array} matching semantic nodes
*/
function findNodes( children, type ) {
	var out = [];
	var i;

	for ( i = 0; i < children.length; i++ ) {
		if ( children[ i ].type === type ) {
			out.push( children[ i ] );
		}
		if ( children[ i ].children ) {
			out = out.concat( findNodes( children[ i ].children, type ) );
		}
	}
	return out;
}

/**
* Returns a diagnostic having a specified code.
*
* @private
* @param {Object} doc - semantic document
* @param {string} code - diagnostic code
* @returns {(Object|null)} diagnostic or null
*/
function findDiagnostic( doc, code ) {
	var i;
	for ( i = 0; i < doc.diagnostics.length; i++ ) {
		if ( doc.diagnostics[ i ].code === code ) {
			return doc.diagnostics[ i ];
		}
	}
	return null;
}


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof convert, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function validates the input value', function test( t ) {
	var values;
	var i;

	values = [
		null,
		void 0,
		true,
		5,
		NaN,
		[],
		{},
		function noop() {}
	];

	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[ i ] ), TypeError, 'throws for '+values[ i ] );
	}
	t.throws( badValue( array2buffer( [ 0xFF ] ) ), TypeError, 'throws for invalid UTF-8' );
	t.end();

	function badValue( value ) {
		return function badValue() {
			convert( value );
		};
	}
});

tape( 'the function validates options', function test( t ) {
	var opts;

	t.throws( badOptions( null ), TypeError, 'throws for a non-object' );
	opts = {
		'mode': 'invalid'
	};
	t.throws( badOptions( opts ), TypeError, 'throws for an invalid mode' );
	opts = {
		'profile': 'invalid'
	};
	t.throws( badOptions( opts ), TypeError, 'throws for an invalid profile' );
	opts = {
		'includePositions': 'true'
	};
	t.throws( badOptions( opts ), TypeError, 'throws for an invalid boolean' );
	t.end();

	function badOptions( options ) {
		return function badOptions() {
			convert( '# Beep', options );
		};
	}
});

tape( 'the function converts equivalent string and Buffer input deterministically', function test( t ) {
	var expected = convert( FIXTURE );
	var actual = convert( string2buffer( FIXTURE ) );

	t.deepEqual( actual, expected, 'returns equivalent documents' );
	t.strictEqual( actual.source.mediaType, 'text/markdown', 'returns media type' );
	t.strictEqual( actual.source.encoding, 'utf-8', 'returns encoding' );
	t.strictEqual( actual.source.lineEnding, 'lf', 'returns line endings' );
	t.strictEqual( actual.schemaVersion, '1.0.0', 'returns schema version' );
	t.end();
});

tape( 'the function converts a representative stdlib README', function test( t ) {
	var related;
	var example;
	var usage;
	var topic;
	var math;
	var doc;
	var c;

	doc = convert( FIXTURE );
	t.strictEqual( doc.titleRef, 'heading[0]', 'identifies the title' );
	t.strictEqual( doc.summaryRef, 'summary[0]', 'identifies the summary' );

	usage = findNode( doc.children, 'section', 'usage' );
	t.strictEqual( usage.headingRef, 'section[usage:0]/heading[0]', 'identifies the usage heading' );
	t.strictEqual( usage.children[ 1 ].role, 'setup', 'classifies setup code' );
	t.strictEqual( usage.children[ 1 ].execution.intent, 'candidate', 'assigns execution intent' );

	topic = findNode( usage.children, 'topic' );
	t.strictEqual( topic.role, 'api-entry-candidate', 'classifies an API topic' );
	t.strictEqual( findNode( topic.children, 'code' ).role, 'usage-example', 'classifies a usage example' );

	example = findNode( findNode( doc.children, 'section', 'examples' ).children, 'code' );
	t.strictEqual( example.role, 'example', 'classifies a main example' );
	t.strictEqual( example.directiveRefs.length, 1, 'attaches an ESLint directive' );

	math = findNode( doc.children, 'math' );
	t.strictEqual( math.label, 'eq:absolute_value', 'attaches an equation label' );
	t.strictEqual( math.alt, 'Absolute value', 'attaches equation alternative text' );

	c = findNode( doc.children, 'section', 'c' );
	t.strictEqual( findNode( c.children, 'code' ).execution.intent, 'not-requested', 'does not request C execution' );

	related = findNode( doc.children, 'section', 'related' );
	t.ok( related.headingRef, 'identifies the related section heading' );

	t.strictEqual( doc.resources.definitions.length, 2, 'collects ordered definitions' );
	t.strictEqual( doc.resources.directives.length, 2, 'collects directives' );
	t.strictEqual( doc.diagnostics.length, 0, 'does not emit diagnostics' );

	t.end();
});

tape( 'the function converts a representative stdlib tutorial', function test( t ) {
	var tutorialSections;
	var tutorialSteps;
	var javascript;
	var embedded;
	var topics;
	var codes;
	var doc;
	var i;

	doc = convert( TUTORIAL_FIXTURE, {
		'mode': 'strict',
		'profile': 'tutorial'
	});
	topics = findNodes( doc.children, 'topic' );
	codes = findNodes( doc.children, 'code' );
	embedded = doc.resources.embeddedCode;

	tutorialSections = 0;
	tutorialSteps = 0;
	javascript = 0;
	for ( i = 0; i < topics.length; i++ ) {
		tutorialSections += ( topics[ i ].role === 'tutorial-section' ) ? 1 : 0;
		tutorialSteps += ( topics[ i ].role === 'tutorial-step' ) ? 1 : 0;
	}
	for ( i = 0; i < codes.length; i++ ) {
		if ( codes[ i ].language === 'javascript' ) {
			t.strictEqual( codes[ i ].role, 'example', 'classifies tutorial JavaScript as an example' );
			t.strictEqual( codes[ i ].execution.intent, 'candidate', 'marks tutorial JavaScript as an execution candidate' );
			javascript += 1;
		}
	}

	t.strictEqual( doc.profile.name, 'tutorial', 'records the tutorial profile' );
	t.strictEqual( doc.titleRef, 'heading[0]', 'identifies the tutorial title' );
	t.strictEqual( doc.summaryRef, 'summary[0]', 'identifies the tutorial summary' );

	t.strictEqual( tutorialSections, 4, 'groups major tutorial sections' );
	t.strictEqual( tutorialSteps, 3, 'groups nested tutorial steps' );

	t.strictEqual( javascript, 5, 'creates standalone JavaScript units' );

	t.strictEqual( codes[ 0 ].role, 'shell-session', 'classifies shell setup as a shell session' );
	t.strictEqual( codes[ 0 ].execution.intent, 'not-requested', 'does not request shell execution' );

	t.strictEqual( embedded.length, 1, 'indexes nested tutorial code' );
	t.strictEqual( embedded[ 0 ].role, 'example', 'classifies nested tutorial JavaScript' );
	t.strictEqual( embedded[ 0 ].execution.intent, 'candidate', 'marks nested tutorial JavaScript as an execution candidate' );

	t.strictEqual( findNodes( doc.children, 'raw' ).length, 0, 'removes stdlib maintenance markup' );
	t.strictEqual( doc.resources.definitions.length, 5, 'collects tutorial link definitions' );
	t.strictEqual( doc.diagnostics.length, 0, 'does not emit diagnostics' );
	t.end();
});

tape( 'the function resolves reference links in projected MDAST', function test( t ) {
	var summary;
	var link;
	var doc;

	doc = convert( FIXTURE );
	summary = findNode( doc.children, 'summary' );
	link = summary.ast.children[ 0 ].children[ 1 ];

	t.strictEqual( link.type, 'link', 'returns an inline link' );
	t.strictEqual( link.url, 'https://en.wikipedia.org/wiki/Absolute_value', 'returns the definition URL' );
	t.strictEqual( link.definitionRef, 'definition[0]', 'returns a definition reference' );
	t.end();
});

tape( 'the function accounts for every root MDAST node', function test( t ) {
	var accounted;
	var count;
	var path;
	var tree;
	var doc;
	var i;

	accounted = {};
	doc = convert( FIXTURE );
	tree = remark().parse( FIXTURE );

	for ( i = 0; i < doc.accounting.length; i++ ) {
		path = doc.accounting[ i ].astPath;
		if ( path.length === 1 ) {
			accounted[ path[ 0 ] ] = true;
		}
	}
	count = keys( accounted ).length;
	t.strictEqual( count, tree.children.length, 'accounts for all root nodes' );
	t.end();
});

tape( 'the function applies immediate run directives', function test( t ) {
	var markdown;
	var code;
	var doc;

	markdown = [
		'# Beep',
		'',
		'> Boop!',
		'',
		'<!-- run-disable -->',
		'',
		'<!-- run: throws: true -->',
		'',
		'```javascript',
		'throw new Error();',
		'```'
	].join( '\n' );
	doc = convert( markdown );
	code = findNode( doc.children, 'code' );

	t.strictEqual( code.execution.disabled, true, 'marks code as disabled' );
	t.strictEqual( code.execution.expected, 'throws', 'records expected throws' );
	t.strictEqual( code.directiveRefs.length, 2, 'attaches contiguous directives' );
	t.end();
});

tape( 'the function preserves source provenance according to options', function test( t ) {
	var markdown;
	var doc;
	var ref;

	markdown = [
		'# Beep',
		'',
		'> Boop!'
	].join( '\r\n' );
	doc = convert( markdown, {
		'includePositions': false,
		'includeSourceSlices': true
	});
	ref = doc.children[ 0 ].source.refs[ 0 ];

	t.strictEqual( doc.source.lineEnding, 'crlf', 'identifies CRLF input' );
	t.strictEqual( ref.range, void 0, 'omits source ranges' );
	t.strictEqual( ref.value, '# Beep', 'includes exact source slices' );
	t.end();
});

tape( 'the function records nested code without elevating it from Markdown', function test( t ) {
	var markdown;
	var doc;

	markdown = [
		'# Beep',
		'',
		'> Boop!',
		'',
		'- Item',
		'',
		'    ```javascript',
		'    var x = 1;',
		'    ```'
	].join( '\n' );
	doc = convert( markdown );

	t.strictEqual( findNode( doc.children, 'code' ), null, 'does not create a code unit' );
	t.strictEqual( doc.resources.embeddedCode.length, 1, 'indexes embedded code' );
	t.end();
});

tape( 'the function creates media and frontmatter units', function test( t ) {
	var markdown;
	var doc;

	markdown = [
		'---',
		'name: beep',
		'---',
		'',
		'# Beep',
		'',
		'> Boop!',
		'',
		'![alt](./image.png)'
	].join( '\n' );
	doc = convert( markdown );

	t.ok( findNode( doc.children, 'frontmatter' ), 'creates frontmatter' );
	t.strictEqual( findNode( doc.children, 'media' ).authoredUrl, './image.png', 'creates media' );
	t.end();
});

tape( 'when in permissive mode, the function preserves malformed section markup', function test( t ) {
	var markdown;
	var doc;
	var raw;

	markdown = [
		'# Beep',
		'',
		'> Boop!',
		'',
		'</section>'
	].join( '\n' );
	doc = convert( markdown );
	raw = findNode( doc.children, 'raw' );

	t.strictEqual( raw.value, '</section>', 'preserves unmatched closing markup' );
	t.ok( findDiagnostic( doc, 'semantic-document/unmatched-section-close' ), 'returns a diagnostic' );
	t.end();
});

tape( 'when in strict mode, the function throws with the partial semantic document', function test( t ) {
	var markdown;
	var error;

	markdown = [
		'# Beep',
		'',
		'> Boop!',
		'',
		'<section class="usage">'
	].join( '\n' );
	try {
		convert( markdown, {
			'mode': 'strict'
		});
	} catch ( err ) {
		error = err;
	}
	t.ok( error.document, 'exposes the partial document' );
	t.ok( findDiagnostic( error.document, 'semantic-document/unclosed-section' ), 'includes the fatal diagnostic' );
	t.end();
});
